// Oeste StatusLine — Mesa theme (v0.2.0).
// Copy-paste ready. Requires: React 18+, Tailwind with dark: variant, JSX transform.
// Requires Mesa tokens: import src/tokens.css once (or copy src/tokens.json).
// Source: https://github.com/eric2busy/Oeste/blob/main/mesa/src/index.js
// Docs: https://oeste.hiddeninwest.com/mesa/#/components/status-line

const MONO = "font-[ui-monospace,'SF_Mono','Cascadia_Code',Menlo,Consolas,monospace]";

const SOFT = "text-[#5b5f65] dark:text-[#a79b82]";

export function StatusLine({ children }) {
  return (
    <p className={`${MONO} flex items-center gap-2 text-[12.5px] ${SOFT}`}>
      <span aria-hidden="true" className="h-2 w-2 animate-pulse rounded-full bg-[#2e6b3e] dark:bg-[#8fae62]" />
      {children}
    </p>
  );
}
